SYNC = '''import copy

def process(data):
    documents = copy.deepcopy(data["initial"])
    tombstones = {}
    events = []
    results = []
    retries = {}
    for key, row in documents.items():
        if type(row["revision"]) is not int or row["revision"] < 1:
            raise ValueError("revision")
    def apply(operations, docs, dead, pending):
        for op in operations:
            key = op["key"]
            if op["type"] not in ("put", "delete"):
                raise ValueError("write type")
            expected = op["expected"]
            if type(expected) is not int or expected < 0:
                raise ValueError("expected")
            revision = docs[key]["revision"] if key in docs else dead.get(key, 0)
            if revision != expected:
                return False
            revision += 1
            if op["type"] == "put":
                value = copy.deepcopy(op["value"])
                docs[key] = {"revision": revision, "value": value}
                dead.pop(key, None)
                pending.append({"key": key, "revision": revision, "deleted": False, "value": value})
            else:
                docs.pop(key, None)
                dead[key] = revision
                pending.append({"key": key, "revision": revision, "deleted": True})
        return True
    for request in data["operations"]:
        kind = request["type"]
        if kind == "get":
            key = request["key"]
            results.append(copy.deepcopy(documents.get(key)))
        elif kind == "changes":
            after, limit = request["after"], request["limit"]
            if type(after) is not int or type(limit) is not int or min(after, limit) < 0:
                raise ValueError("cursor")
            selected = [event for event in events if event["sequence"] > after][:limit]
            results.append({"events": copy.deepcopy(selected), "cursor": selected[-1]["sequence"] if selected else after})
        elif kind == "transaction":
            token = request["id"]
            ops = request["writes"]
            if token in retries:
                previous, result = retries[token]
                if previous != ops:
                    raise ValueError("id reuse")
                results.append(copy.deepcopy(result))
                continue
            docs, dead, pending = copy.deepcopy(documents), dict(tombstones), []
            accepted = apply(ops, docs, dead, pending)
            result = {"accepted": accepted, "cursor": len(events)}
            if accepted:
                documents, tombstones = docs, dead
                for event in pending:
                    event["sequence"] = len(events) + 1
                    events.append(event)
                result["cursor"] = len(events)
            retries[token] = (copy.deepcopy(ops), copy.deepcopy(result))
            results.append(result)
        else:
            raise ValueError("operation")
    return {"documents": documents, "tombstones": tombstones, "results": results}
'''

QUEUE = '''import copy

def process(data):
    jobs = copy.deepcopy(data["jobs"])
    capacity = data["capacity"]
    if type(capacity) is not int or capacity < 1:
        raise ValueError("capacity")
    if len({job["id"] for job in jobs}) != len(jobs):
        raise ValueError("duplicate")
    by_id = {job["id"]: job for job in jobs}
    for job in jobs:
        if type(job["attempts"]) is not int or job["attempts"] < 1:
            raise ValueError("attempts")
        if any(dep not in by_id for dep in job["requires"]):
            raise ValueError("missing dependency")
    remaining = set(by_id)
    while remaining:
        ready = {key for key in remaining if not (set(by_id[key]["requires"]) & remaining)}
        if not ready:
            raise ValueError("cycle")
        remaining -= ready
    state = {key: {"status": "pending", "attempt": 0} for key in by_id}
    history = []
    def block_dependents():
        changed = True
        while changed:
            changed = False
            for job in jobs:
                if state[job["id"]]["status"] == "pending" and any(state[dep]["status"] in ("failed", "cancelled", "blocked") for dep in job["requires"]):
                    state[job["id"]]["status"] = "blocked"
                    changed = True
    for operation in data["operations"]:
        kind = operation["type"]
        if kind == "dispatch":
            block_dependents()
            active = sum(row["status"] == "running" for row in state.values())
            ready = [job for job in jobs if state[job["id"]]["status"] == "pending" and all(state[dep]["status"] == "succeeded" for dep in job["requires"])]
            ready.sort(key=lambda job: (-job["priority"], job["id"]))
            started = []
            for job in ready[:max(0, capacity-active)]:
                row = state[job["id"]]
                row["attempt"] += 1
                row["status"] = "running"
                started.append({"id": job["id"], "attempt": row["attempt"]})
            history.append(started)
        elif kind == "finish":
            key, attempt = operation["id"], operation["attempt"]
            if key not in state or type(attempt) is not int or type(operation["success"]) is not bool:
                raise ValueError("finish")
            row = state[key]
            if row["status"] != "running" or attempt != row["attempt"]:
                history.append(False)
                continue
            row["status"] = "succeeded" if operation["success"] else "pending" if attempt < by_id[key]["attempts"] else "failed"
            block_dependents()
            history.append(True)
        elif kind == "cancel":
            key = operation["id"]
            if key not in state:
                raise ValueError("cancel")
            row = state[key]
            changed = row["status"] in ("pending", "running")
            if changed:
                row["status"] = "cancelled"
            block_dependents()
            history.append(changed)
        else:
            raise ValueError("operation")
    return {"state": state, "history": history}
'''

WAREHOUSE = '''import copy

def process(data):
    stock = copy.deepcopy(data["stock"])
    if any(type(value) is not int or value < 0 for site in stock.values() for value in site.values()):
        raise ValueError("stock")
    reservations = {}
    seen = {}
    audit = []
    results = []
    for operation in data["operations"]:
        token = operation["id"]
        if token in seen:
            old, result = seen[token]
            if old != operation:
                raise ValueError("id reuse")
            results.append(result)
            continue
        candidate = copy.deepcopy(stock)
        holds = copy.deepcopy(reservations)
        kind = operation["type"]
        if kind == "transfer":
            source, target, sku, quantity = (operation[key] for key in ("source", "target", "sku", "quantity"))
            if type(quantity) is not int or quantity < 1:
                raise ValueError("quantity")
            valid = source in candidate and target in candidate and sku in candidate[source] and sku in candidate[target]
            if valid:
                candidate[source][sku] -= quantity
                candidate[target][sku] += quantity
        elif kind == "reserve":
            name, site, sku, quantity = (operation[key] for key in ("reservation", "site", "sku", "quantity"))
            if type(quantity) is not int or quantity < 1:
                raise ValueError("quantity")
            valid = name not in holds and site in candidate and sku in candidate[site]
            if valid:
                candidate[site][sku] -= quantity
                holds[name] = {"site": site, "sku": sku, "quantity": quantity}
        elif kind in ("release", "ship"):
            name = operation["reservation"]
            valid = name in holds
            if valid:
                hold = holds.pop(name)
                if kind == "release":
                    candidate[hold["site"]][hold["sku"]] += hold["quantity"]
        else:
            raise ValueError("operation")
        valid = valid and all(value >= 0 for site in candidate.values() for value in site.values())
        if valid:
            stock, reservations = candidate, holds
            audit.append({"sequence": len(audit)+1, "id": token, "type": kind})
        seen[token] = (copy.deepcopy(operation), valid)
        results.append(valid)
    return {"stock": stock, "reservations": reservations, "audit": audit, "results": results}
'''

BOOKING = '''import copy
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

def process(data):
    rooms = data["rooms"]
    rates = {}
    for key, value in rooms.items():
        if not isinstance(value, str):
            raise ValueError("rate")
        try:
            rate = Decimal(value)
        except (InvalidOperation, TypeError):
            raise ValueError("rate") from None
        if not rate.is_finite() or rate < 0:
            raise ValueError("rate")
        rates[key] = rate
    bookings, seen, results = {}, {}, []
    for operation in data["operations"]:
        token = operation["id"]
        if token in seen:
            old, result = seen[token]
            if old != operation:
                raise ValueError("id reuse")
            results.append(copy.deepcopy(result))
            continue
        kind = operation["type"]
        if kind == "book":
            name, room, start, duration, count, period = (operation[key] for key in ("booking", "room", "start", "duration", "count", "period"))
            if any(type(value) is not int for value in (start, duration, count, period)) or start < 0 or min(duration, count, period) < 1:
                raise ValueError("schedule")
            intervals = [[start+i*period, start+i*period+duration] for i in range(count)]
            all_other = [interval for row in bookings.values() if row["room"] == room for interval in row["intervals"]]
            valid = room in rates and name not in bookings
            combined = sorted(intervals + all_other)
            valid = valid and all(a[1] <= b[0] for a, b in zip(combined, combined[1:]))
            if valid:
                with localcontext() as context:
                    rate = rates[room]
                    context.prec = max(28, len(rate.as_tuple().digits)+abs(rate.as_tuple().exponent)+len(str(duration))+len(str(count))+4)
                    charge = format((rate*duration*count).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP), "f")
                bookings[name] = {"room": room, "intervals": intervals, "charge": charge}
                result = {"accepted": True, "charge": charge}
            else:
                result = {"accepted": False}
        elif kind == "cancel":
            name = operation["booking"]
            result = {"accepted": name in bookings}
            bookings.pop(name, None)
        else:
            raise ValueError("operation")
        seen[token] = (copy.deepcopy(operation), copy.deepcopy(result))
        results.append(result)
    return {"bookings": bookings, "results": results}
'''

